"""Tensor-parallel linear layers (Megatron-style).

Weight layout follows torch.nn.Linear: weight has shape (out_features, in_features)
and y = x @ W^T + b.

ColumnParallelLinear: the output dimension is sharded (columns of A in Y = X A).
    Each rank holds weight[out/ws, in] and bias[out/ws]. The local outputs are
    gathered (all_gather) along the last dimension.

RowParallelLinear: the input dimension is sharded (rows of A in Y = X A).
    Each rank holds weight[out, in/ws] and the full bias[out]. The partial
    outputs are summed (all_reduce) and the bias is added afterwards.
"""

import torch
import torch.distributed as dist
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _divide(a, b):
    assert a % b == 0, f"{a} is not divisible by {b}"
    return a // b


# --------------------------------------------------------------------------- #
# Communication primitives with correct autograd semantics
# --------------------------------------------------------------------------- #
def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous().clone()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _split_last(x):
    ws = _world_size()
    if ws == 1:
        return x
    chunk = _divide(x.size(-1), ws)
    return x.narrow(-1, _rank() * chunk, chunk).contiguous()


def _gather_last(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad)


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x)

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take local chunk of last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last(x)

    @staticmethod
    def backward(ctx, grad):
        return _gather_last(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: take local chunk."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last(grad)


# --------------------------------------------------------------------------- #
# Layers
# --------------------------------------------------------------------------- #
class ColumnParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.out_features_per_partition = _divide(out_features, self.world_size)

        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight must have shape ({out_features}, {in_features}), "
            f"got {tuple(master_weight.shape)}"
        )
        n = self.out_features_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[self.rank * n:(self.rank + 1) * n, :]
            self.weight = torch.nn.Parameter(shard.clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(n, dtype=self.weight.dtype, device=self.weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        local = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(local)


class RowParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.in_features_per_partition = _divide(in_features, self.world_size)

        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight must have shape ({out_features}, {in_features}), "
            f"got {tuple(master_weight.shape)}"
        )
        n = self.in_features_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[:, self.rank * n:(self.rank + 1) * n]
            self.weight = torch.nn.Parameter(shard.clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(out_features, dtype=self.weight.dtype,
                            device=self.weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split it here) or an already-partitioned input.
        if self.world_size > 1 and x.size(-1) == self.in_features:
            x = _ScatterToParallelRegion.apply(x)
        elif x.size(-1) != self.in_features_per_partition:
            raise ValueError(
                f"Expected input last dim {self.in_features} or "
                f"{self.in_features_per_partition}, got {x.size(-1)}"
            )
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
